args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-omics-library-next/milo');PD<-file.path(P,'results/plot_data');library(ggplot2);library(grid);library(ggbeeswarm);set.seed(20261030)
