lineages<-c('MPs','pDCs','ILCs','T cells','B cells','Plasma B','Mast cells','Endothelia','Mesenchyme','Mesothelia','Hepatocytes','Cholangiocytes');ng<-c(5,1,3,4,2,2,1,7,3,1,1,3);centers<-data.frame(lineage=lineages,x=c(0,-.1,-2.5,-4.5,.6,1.2,-5.2,3.6,5.9,6.2,3.5,3.1),y=c(5,2.3,-4.4,.3,1.8,.4,2.0,-3.1,.6,-.2,2.3,2.9))
