nodes<-do.call(rbind,nh);membership<-do.call(rbind,members);totC<-sum(cells$condition=='Cirrhotic');totU<-nrow(cells)-totC;nodes$log2_ratio<-log2(((nodes$n_Cirrhotic+.5)/(totC+1))/((nodes$n_Uninjured+.5)/(totU+1)));nodes$display_ratio<-ifelse(abs(nodes$log2_ratio)>.7,nodes$log2_ratio,NA)
M<-Matrix::sparseMatrix(i=match(membership$Nhood,nodes$Nhood),j=match(membership$cell_id,cells$cell_id),x=1,dims=c(nrow(nodes),nrow(cells)));ov<-as.matrix(Matrix::tcrossprod(M));ind<-which(upper.tri(ov)&ov>=3,arr.ind=TRUE);edges<-data.frame(from=nodes$Nhood[ind[,1]],to=nodes$Nhood[ind[,2]],overlap=ov[ind]);edges$x<-nodes$x[ind[,1]];edges$y<-nodes$y[ind[,1]];edges$xend<-nodes$x[ind[,2]];edges$yend<-nodes$y[ind[,2]]
endo<-which(cells$lineage=='Endothelia');ei<-which(nodes$lineage=='Endothelia');# e uses a transparent local transform of the same cells, not a new stochastic UMAP
cells$endo_x<-ifelse(cells$lineage=='Endothelia',(cells$x-3.6)*2.5,NA);cells$endo_y<-ifelse(cells$lineage=='Endothelia',(cells$y+3.1)*2,NA);nodes$endo_x<-cells$endo_x[match(nodes$index_cell_id,cells$cell_id)];nodes$endo_y<-cells$endo_y[match(nodes$index_cell_id,cells$cell_id)]
